```java
class Report {
    // 생성 횟수는 공유하고 수량은 각 객체에 둬요.
    static int count = 0;
    int qty = 3;
    Report() { count++; }
}

public class Main {
    public static void main(String[] args) {
        Report first = new Report();
        Report second = new Report();
        second.qty = 8;
        System.out.println(Report.count + ":" + first.qty);
    }
}
```

